-- ui.pinned_notes: a note pinned to one thing of the design or the tool, or to the whole schema, for people and the agent; it goes when what it is pinned to goes. Owner: ui.
CREATE TABLE ui.pinned_notes (
  id            BIGINT NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,                                   -- issued by the database
  namespace     BIGINT REFERENCES cortex.namespaces (id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,       -- the namespace it is pinned to; NULL when pinned elsewhere
  object        BIGINT REFERENCES cortex.objects (id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,          -- the object it is pinned to; NULL when pinned elsewhere
  "column"      BIGINT REFERENCES cortex.columns (id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,          -- the column it is pinned to; NULL when pinned elsewhere
  "constraint"  BIGINT REFERENCES cortex.constraints (id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,      -- the key, check or link it is pinned to; NULL when pinned elsewhere
  "index"       BIGINT REFERENCES cortex.indexes (id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,          -- the index it is pinned to; NULL when pinned elsewhere
  area          BIGINT REFERENCES ui.subject_areas (id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,        -- the subject area it is pinned to; NULL when pinned elsewhere
  perspective   BIGINT REFERENCES ui.custom_perspectives (id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,  -- the perspective it is pinned to; NULL when pinned elsewhere
  turn          UUID REFERENCES cortex.turns (id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,              -- the turn it is pinned to; NULL when pinned elsewhere
  position      NUMERIC NOT NULL UNIQUE CHECK (position > 0),                                                   -- its place among the notes; an order key
  text          TEXT NOT NULL CHECK (length(text) >= 1),                                                        -- the note, as written
  done          BOOLEAN NOT NULL DEFAULT false,                                                                 -- true once it has been worked through
  written_by    TEXT NOT NULL CHECK (length(written_by) >= 1),                                                  -- who wrote it: a person's name or the agent's label
  CHECK (num_nonnulls(namespace, object, "column", "constraint", "index", area, perspective, turn) <= 1)
);

COMMENT ON TABLE ui.pinned_notes IS 'a note pinned to one thing of the design or the tool, or to the whole schema, for people and the agent; it goes when what it is pinned to goes.';
COMMENT ON COLUMN ui.pinned_notes.id IS 'issued by the database';
COMMENT ON COLUMN ui.pinned_notes.namespace IS 'the namespace it is pinned to; NULL when pinned elsewhere';
COMMENT ON COLUMN ui.pinned_notes.object IS 'the object it is pinned to; NULL when pinned elsewhere';
COMMENT ON COLUMN ui.pinned_notes."column" IS 'the column it is pinned to; NULL when pinned elsewhere';
COMMENT ON COLUMN ui.pinned_notes."constraint" IS 'the key, check or link it is pinned to; NULL when pinned elsewhere';
COMMENT ON COLUMN ui.pinned_notes."index" IS 'the index it is pinned to; NULL when pinned elsewhere';
COMMENT ON COLUMN ui.pinned_notes.area IS 'the subject area it is pinned to; NULL when pinned elsewhere';
COMMENT ON COLUMN ui.pinned_notes.perspective IS 'the perspective it is pinned to; NULL when pinned elsewhere';
COMMENT ON COLUMN ui.pinned_notes.turn IS 'the turn it is pinned to; NULL when pinned elsewhere';
COMMENT ON COLUMN ui.pinned_notes.position IS 'its place among the notes; an order key';
COMMENT ON COLUMN ui.pinned_notes.text IS 'the note, as written';
COMMENT ON COLUMN ui.pinned_notes.done IS 'true once it has been worked through';
COMMENT ON COLUMN ui.pinned_notes.written_by IS 'who wrote it: a person''s name or the agent''s label';
